//! The public key the app trusts for update signatures.

/// The Ed25519 public key that verifies update signatures.
///
/// Generated with `cargo xtask keygen` (see docs/RELEASING.md); the matching private key is the
/// repository secret UPDATE_SIGNING_KEY and the matching variable is UPDATE_PUBLIC_KEY. All zeros
/// would mean "not set up": the app then refuses to update. Never commit a key that was not
/// generated by that command.
pub const UPDATE_PUBLIC_KEY: [u8; 32] = [
    0xe6, 0x49, 0xcd, 0xbe, 0x6d, 0x99, 0xb5, 0x82, 0x1e, 0x17, 0xf1, 0xa0, 0xe1, 0xac, 0xcb, 0xd6,
    0x3d, 0xae, 0x29, 0xd1, 0xbc, 0x26, 0x0a, 0x6d, 0x8a, 0x69, 0xe4, 0x09, 0x80, 0x7b, 0x8b, 0xdc,
];

/// Whether `key` is a real key and not the all-zero placeholder.
pub fn is_configured(key: &[u8; 32]) -> bool {
    key.iter().any(|byte| *byte != 0)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_all_zero_key_is_not_configured() {
        assert!(!is_configured(&[0; 32]));
    }

    #[test]
    fn the_committed_key_is_configured_and_a_valid_ed25519_point() {
        assert!(is_configured(&UPDATE_PUBLIC_KEY));
        assert!(ed25519_dalek::VerifyingKey::from_bytes(&UPDATE_PUBLIC_KEY).is_ok());
    }

    #[test]
    fn any_other_key_is_configured() {
        let mut key = [0; 32];
        key[31] = 1;
        assert!(is_configured(&key));
    }
}
